const regUpdateNames={name:'nombre',phone:'teléfono',email:'correo',document:'cédula',photo:'foto de perfil',vehicle_photo:'foto del vehículo',vehicle_plate_photo:'foto de la placa',vehicle_mileage:'kilometraje'};
