  initial:{identity:identityField?'':'new',open_order:hasOrder?'false':'true',type:'repair',priority:'normal',v_photo:Boolean(known&&!known.photo_id),v_plate_photo:Boolean(known&&!known.plate_photo_id)},cta:'Aceptar registro',success:`${r.code} aceptado`,
