 <div className="detail-summary"><div><small>Cliente</small><b>{order.client_name}</b></div><div><small>Ingreso</small><b>{date(order.created_at)}</b></div><div><small>Servicio</small><b>{typeNames[order.type]}</b></div><div><small>Ubicación actual</small><b>{order.location}</b></div></div>
